package com.learnspace.controller;
import com.learnspace.model.*; import com.learnspace.repository.EnrollmentRepository; import com.learnspace.repository.UserRepository; import jakarta.servlet.http.HttpSession; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users;private final EnrollmentRepository enrollments;private final PasswordEncoder encoder; AuthController(UserRepository u,EnrollmentRepository n,PasswordEncoder e){users=u;enrollments=n;encoder=e;} record Login(@Email String email,@NotBlank String password){} record Register(@NotBlank String displayName,@Email String email,@Size(min=8) String password){} record Profile(@NotBlank String displayName,@Email String email){} record UserView(Long id,String displayName,String email,Role role){}
 private AppUser current(HttpSession s){Long id=(Long)s.getAttribute("user");if(id==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));} private UserView view(AppUser u){return new UserView(u.getId(),u.getDisplayName(),u.getEmail(),u.getRole());} @PostMapping("/register") public UserView register(@RequestBody Register r){if(users.findByEmail(r.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");AppUser u=new AppUser();u.setDisplayName(r.displayName());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setRole(Role.STUDENT);return view(users.save(u));} @PostMapping("/login") public UserView login(@RequestBody Login r,HttpSession s){AppUser u=users.findByEmail(r.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid login"));if(!encoder.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid login");s.setAttribute("user",u.getId());return view(u);} @GetMapping("/me") public UserView me(HttpSession s){return view(current(s));} @PatchMapping("/me") public UserView update(@RequestBody Profile p,HttpSession s){AppUser u=current(s);users.findByEmail(p.email()).filter(found->!found.getId().equals(u.getId())).ifPresent(found->{throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");});u.setDisplayName(p.displayName());u.setEmail(p.email());return view(users.save(u));} @DeleteMapping("/me") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(HttpSession s){AppUser u=current(s);enrollments.deleteAll(enrollments.findByStudentId(u.getId()));users.delete(u);s.invalidate();} @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(HttpSession s){s.invalidate();} }
